-- msvc-ventas | DB: ventas
-- Schema + seed mínimo. id_cliente / id_evento / id_sector = refs lógicas (sin FK cross-DB).
-- IDs fijos: infrastructure/mysql/README.md

SET NAMES utf8mb4;
SET time_zone = '+00:00';

CREATE TABLE IF NOT EXISTS reserva (
  id_reserva       CHAR(36)       NOT NULL,
  id_cliente       CHAR(36)       NOT NULL COMMENT 'ref lógica usuarios.usuario',
  id_evento        CHAR(36)       NOT NULL COMMENT 'ref lógica eventos.evento',
  fecha_creacion   DATETIME(3)    NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  fecha_expiracion DATETIME(3)    NOT NULL,
  estado           VARCHAR(32)    NOT NULL,
  total            DECIMAL(12, 2) NOT NULL DEFAULT 0,
  PRIMARY KEY (id_reserva),
  KEY ix_reserva_cliente (id_cliente),
  KEY ix_reserva_evento (id_evento)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS detalle_reserva (
  id_detalle       CHAR(36)       NOT NULL,
  id_reserva       CHAR(36)       NOT NULL,
  id_sector        CHAR(36)       NOT NULL COMMENT 'ref lógica eventos.sector',
  cantidad         INT            NOT NULL DEFAULT 1,
  precio_unitario  DECIMAL(12, 2) NOT NULL,
  PRIMARY KEY (id_detalle),
  CONSTRAINT fk_detalle_reserva FOREIGN KEY (id_reserva) REFERENCES reserva (id_reserva)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS compra (
  id_compra    CHAR(36)       NOT NULL,
  id_reserva   CHAR(36)       NULL,
  id_cliente   CHAR(36)       NOT NULL COMMENT 'ref lógica usuarios.usuario',
  fecha_compra DATETIME(3)    NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  total        DECIMAL(12, 2) NOT NULL,
  moneda       CHAR(3)        NOT NULL DEFAULT 'ARS',
  estado       VARCHAR(32)    NOT NULL,
  emision_estado       VARCHAR(16)  NOT NULL DEFAULT 'NO_REQUIERE' COMMENT 'NO_REQUIERE|PENDIENTE|EMITIDA|FALLIDA',
  emision_intentos     INT          NOT NULL DEFAULT 0,
  emision_ultimo_error VARCHAR(255) NULL,
  emision_actualizado  DATETIME(3)  NULL,
  PRIMARY KEY (id_compra),
  KEY ix_compra_cliente (id_cliente),
  KEY ix_compra_emision (estado, emision_estado),
  CONSTRAINT fk_compra_reserva FOREIGN KEY (id_reserva) REFERENCES reserva (id_reserva)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS pago (
  id_pago                  CHAR(36)       NOT NULL,
  id_compra                CHAR(36)       NOT NULL,
  proveedor                VARCHAR(64)    NOT NULL,
  id_transaccion_externa   VARCHAR(128)   NOT NULL,
  monto                    DECIMAL(12, 2) NOT NULL,
  estado                   VARCHAR(32)    NOT NULL,
  fecha_pago               DATETIME(3)    NULL,
  PRIMARY KEY (id_pago),
  UNIQUE KEY uk_pago_tx_externa (id_transaccion_externa),
  CONSTRAINT fk_pago_compra FOREIGN KEY (id_compra) REFERENCES compra (id_compra)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS cupo_sector (
  id_cupo              CHAR(36) NOT NULL,
  id_evento            CHAR(36) NOT NULL COMMENT 'ref lógica eventos.evento',
  id_sector            CHAR(36) NOT NULL COMMENT 'ref lógica eventos.sector',
  capacidad_total      INT      NOT NULL,
  cantidad_disponible  INT      NOT NULL,
  cantidad_reservada   INT      NOT NULL DEFAULT 0,
  cantidad_vendida     INT      NOT NULL DEFAULT 0,
  PRIMARY KEY (id_cupo),
  UNIQUE KEY uk_cupo_evento_sector (id_evento, id_sector)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Asientos virtuales: solo existe una fila por asiento TOMADO (RESERVADO|VENDIDO); los libres no se persisten.
-- La clave única es la segunda línea de defensa contra la doble venta de un mismo asiento.
CREATE TABLE IF NOT EXISTS asiento_reservado (
  id_asiento_reservado CHAR(36)    NOT NULL,
  id_reserva           CHAR(36)    NOT NULL,
  id_evento            CHAR(36)    NOT NULL COMMENT 'ref lógica eventos.evento',
  id_sector            CHAR(36)    NOT NULL COMMENT 'ref lógica eventos.sector',
  fila                 VARCHAR(8)  NOT NULL,
  numero               INT         NOT NULL,
  estado               VARCHAR(16) NOT NULL COMMENT 'RESERVADO|VENDIDO',
  PRIMARY KEY (id_asiento_reservado),
  UNIQUE KEY uk_asiento_evento_sector_fila_numero (id_evento, id_sector, fila, numero),
  KEY ix_asiento_reserva (id_reserva),
  CONSTRAINT fk_asiento_reserva FOREIGN KEY (id_reserva) REFERENCES reserva (id_reserva)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Cupos alineados a sectores seed de eventos (d001–d00e)
-- IDs f001–f005 + f050–f065 (evitar choque con reserva/compra f011…)
ON DUPLICATE KEY UPDATE
  capacidad_total = VALUES(capacidad_total),
  cantidad_disponible = VALUES(cantidad_disponible),
  cantidad_vendida = VALUES(cantidad_vendida);

-- Compra aprobada cliente demo → Metallica (campo)
   '2026-10-01 14:00:00.000', '2026-10-01 14:10:00.000', 'COMPRADA', 95000.00)
ON DUPLICATE KEY UPDATE estado = VALUES(estado), total = VALUES(total);

   'c0000000-0000-4000-8000-000000000011', 1, 95000.00)
ON DUPLICATE KEY UPDATE cantidad = VALUES(cantidad), precio_unitario = VALUES(precio_unitario);

   'b0000000-0000-4000-8000-000000000001', '2026-10-01 14:05:00.000', 95000.00, 'ARS', 'APROBADA',
   'EMITIDA', 1, NULL, '2026-10-01 14:05:35.000')
ON DUPLICATE KEY UPDATE estado = VALUES(estado), total = VALUES(total), emision_estado = VALUES(emision_estado);

   'MERCADO_PAGO', 'mp_seed_tx_001', 95000.00, 'APROBADO', '2026-10-01 14:05:30.000')
ON DUPLICATE KEY UPDATE estado = VALUES(estado), monto = VALUES(monto);

-- Compra sobre evento cancelado (Rock in Rio) → reintegro / entradas
   '2026-09-15 10:00:00.000', '2026-09-15 10:10:00.000', 'COMPRADA', 75000.00)
ON DUPLICATE KEY UPDATE estado = VALUES(estado), total = VALUES(total);

   'c0000000-0000-4000-8000-000000000013', 1, 75000.00)
ON DUPLICATE KEY UPDATE cantidad = VALUES(cantidad), precio_unitario = VALUES(precio_unitario);

   'b0000000-0000-4000-8000-000000000001', '2026-09-15 10:05:00.000', 75000.00, 'ARS', 'APROBADA',
   'EMITIDA', 1, NULL, '2026-09-15 10:05:35.000')
ON DUPLICATE KEY UPDATE estado = VALUES(estado), total = VALUES(total), emision_estado = VALUES(emision_estado);

   'MERCADO_PAGO', 'mp_seed_tx_cancel_001', 75000.00, 'APROBADO', '2026-09-15 10:05:30.000')
ON DUPLICATE KEY UPDATE estado = VALUES(estado), monto = VALUES(monto);

-- Cupos de los eventos agregados para el hero (Ghost, Turmion, RHCP, Boca, Dakar, MotoGP, UFC).
-- Sin estas filas el catálogo los mostraba como "Agotado".
ON DUPLICATE KEY UPDATE
  capacidad_total = VALUES(capacidad_total),
  cantidad_disponible = VALUES(cantidad_disponible),
  cantidad_vendida = VALUES(cantidad_vendida);


-- ============================================================================
-- Plataforma en funcionamiento: cupos con distintos niveles, compras de varios clientes
-- (aprobadas, rechazada, emisión pendiente/fallida, reserva expirada) y asientos vendidos.
-- ============================================================================
ON DUPLICATE KEY UPDATE
  capacidad_total = VALUES(capacidad_total),
  cantidad_disponible = VALUES(cantidad_disponible),
  cantidad_vendida = VALUES(cantidad_vendida);

